from paraview.simple import *
r=XMLImageDataReader(FileName=['fracture.vti']); s=TTKTopologicalSimplificationByPersistence(Input=r);s.InputArray=['POINTS','Scalars_'];s.PersistenceThreshold=.05;m=TTKMorseSmaleComplex(Input=s);m.ScalarField=['POINTS','Scalars_'];m.UpdatePipeline()
for port in range(7):
 try:
  i=m.GetDataInformation(port);pd=i.GetPointDataInformation();cd=i.GetCellDataInformation(); print('PORT',port,i.GetDataSetTypeAsString(),i.GetNumberOfPoints(),i.GetNumberOfCells(),'PD',[pd.GetArrayInformation(a).GetName() for a in range(pd.GetNumberOfArrays())],'CD',[cd.GetArrayInformation(a).GetName() for a in range(cd.GetNumberOfArrays())])
 except Exception as e: print('ERR',port,e)
PY"

